package com.huy.enterprise.shipment;
import java.util.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/shipments") @RequiredArgsConstructor public class ShipmentController{private final ShipmentService service;@GetMapping public List<ShipmentResponse> all(){return service.all();}@GetMapping("/{id}") public ShipmentResponse one(@PathVariable UUID id){return service.one(id);}@PostMapping @ResponseStatus(HttpStatus.CREATED) public ShipmentResponse create(@Valid @RequestBody CreateShipmentRequest r){return service.create(r);}@PutMapping("/{id}") public ShipmentResponse update(@PathVariable UUID id,@Valid @RequestBody UpdateShipmentRequest r){return service.update(id,r);}@PatchMapping("/{id}/status") public ShipmentResponse status(@PathVariable UUID id,@Valid @RequestBody UpdateShipmentStatusRequest r){return service.status(id,r.status());}}
